-- Drawing categories with default pricing
CREATE TABLE IF NOT EXISTS drawing_categories (
    id BIGSERIAL PRIMARY KEY,
    drawing_number VARCHAR(100) NOT NULL,
    category VARCHAR(50) NOT NULL,
    default_price DECIMAL(15, 2),
    created_at TIMESTAMP DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_drawing_cat_number ON drawing_categories(drawing_number);
CREATE INDEX IF NOT EXISTS idx_drawing_cat_category ON drawing_categories(category);
